    dst_p[1] |= pack_left_shift_u8(src_p->bypass1, 0u, 0x01u);
    dst_p[1] |= pack_left_shift_u8(src_p->bypass2, 1u, 0x02u);
    dst_p[1] |= pack_left_shift_u8(src_p->battery_voltage_limit, 2u, 0x04u);
