    dst_p[1] |= pack_left_shift_u8(src_p->pi_limit, 5u, 0x20u);
    dst_p[1] |= pack_left_shift_u8(src_p->cp_limit, 6u, 0x40u);
    dst_p[1] |= pack_left_shift_u8(src_p->power_limit, 7u, 0x80u);
    dst_p[2] |= pack_left_shift_u8(src_p->mains_max_current_limit, 0u, 0x01u);
