    dst_p->mains_current_limit = unpack_right_shift_u8(src_p[1], 4u, 0x10u);
    dst_p->pi_limit = unpack_right_shift_u8(src_p[1], 5u, 0x20u);
    dst_p->cp_limit = unpack_right_shift_u8(src_p[1], 6u, 0x40u);
    dst_p->power_limit = unpack_right_shift_u8(src_p[1], 7u, 0x80u);
    dst_p->mains_max_current_limit = unpack_right_shift_u8(src_p[2], 0u, 0x01u);
    dst_p->battery_mx_current_limit = unpack_right_shift_u8(src_p[2], 1u, 0x02u);
    dst_p->battery_max_voltage_limit = unpack_right_shift_u8(src_p[2], 2u, 0x04u);
    dst_p->capacitor_temp_limit = unpack_right_shift_u8(src_p[2], 3u, 0x08u);
    dst_p->power_stage_temp_limit = unpack_right_shift_u8(src_p[2], 4u, 0x10u);
    dst_p->diode_temp_limit = unpack_right_shift_u8(src_p[2], 5u, 0x20u);
