int ucr_03_apps_pack(
    uint8_t *dst_p,
    const struct ucr_03_apps_t *src_p,
    size_t size)
{
    uint32_t apps1_percent_travel;
    uint32_t apps2_percent_travel;
    uint32_t torque_percent;

    if (size < 32u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 32);

    memcpy(&apps1_percent_travel, &src_p->apps1_percent_travel, sizeof(apps1_percent_travel));
    dst_p[0] |= pack_left_shift_u32(apps1_percent_travel, 0u, 0xffu);
    dst_p[1] |= pack_right_shift_u32(apps1_percent_travel, 8u, 0xffu);
    dst_p[2] |= pack_right_shift_u32(apps1_percent_travel, 16u, 0xffu);
    dst_p[3] |= pack_right_shift_u32(apps1_percent_travel, 24u, 0xffu);
    memcpy(&apps2_percent_travel, &src_p->apps2_percent_travel, sizeof(apps2_percent_travel));
    dst_p[4] |= pack_left_shift_u32(apps2_percent_travel, 0u, 0xffu);
    dst_p[5] |= pack_right_shift_u32(apps2_percent_travel, 8u, 0xffu);
    dst_p[6] |= pack_right_shift_u32(apps2_percent_travel, 16u, 0xffu);
    dst_p[7] |= pack_right_shift_u32(apps2_percent_travel, 24u, 0xffu);
    memcpy(&torque_percent, &src_p->torque_percent, sizeof(torque_percent));
    dst_p[8] |= pack_left_shift_u32(torque_percent, 0u, 0xffu);
    dst_p[9] |= pack_right_shift_u32(torque_percent, 8u, 0xffu);
    dst_p[10] |= pack_right_shift_u32(torque_percent, 16u, 0xffu);
    dst_p[11] |= pack_right_shift_u32(torque_percent, 24u, 0xffu);
    dst_p[12] |= pack_left_shift_u8(src_p->apps_fault, 0u, 0x01u);

    return (32);
}

int ucr_03_apps_unpack(
    struct ucr_03_apps_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    uint32_t apps1_percent_travel;
    uint32_t apps2_percent_travel;
    uint32_t torque_percent;

    if (size < 32u) {
        return (-EINVAL);
    }

    apps1_percent_travel = unpack_right_shift_u32(src_p[0], 0u, 0xffu);
    apps1_percent_travel |= unpack_left_shift_u32(src_p[1], 8u, 0xffu);
    apps1_percent_travel |= unpack_left_shift_u32(src_p[2], 16u, 0xffu);
    apps1_percent_travel |= unpack_left_shift_u32(src_p[3], 24u, 0xffu);
    memcpy(&dst_p->apps1_percent_travel, &apps1_percent_travel, sizeof(dst_p->apps1_percent_travel));
    apps2_percent_travel = unpack_right_shift_u32(src_p[4], 0u, 0xffu);
    apps2_percent_travel |= unpack_left_shift_u32(src_p[5], 8u, 0xffu);
    apps2_percent_travel |= unpack_left_shift_u32(src_p[6], 16u, 0xffu);
    apps2_percent_travel |= unpack_left_shift_u32(src_p[7], 24u, 0xffu);
    memcpy(&dst_p->apps2_percent_travel, &apps2_percent_travel, sizeof(dst_p->apps2_percent_travel));
    torque_percent = unpack_right_shift_u32(src_p[8], 0u, 0xffu);
    torque_percent |= unpack_left_shift_u32(src_p[9], 8u, 0xffu);
    torque_percent |= unpack_left_shift_u32(src_p[10], 16u, 0xffu);
    torque_percent |= unpack_left_shift_u32(src_p[11], 24u, 0xffu);
    memcpy(&dst_p->torque_percent, &torque_percent, sizeof(dst_p->torque_percent));
    dst_p->apps_fault = unpack_right_shift_u8(src_p[12], 0u, 0x01u);

    return (0);
}

