int ucr_03_accumulator_measurements_pack(
    uint8_t *dst_p,
    const struct ucr_03_accumulator_measurements_t *src_p,
    size_t size)
{
    uint32_t battery_current;
    uint32_t battery_power;
    uint32_t battery_voltage;
    uint32_t ts_voltage;

    if (size < 20u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 20);

    memcpy(&battery_current, &src_p->battery_current, sizeof(battery_current));
    dst_p[0] |= pack_left_shift_u32(battery_current, 0u, 0xffu);
    dst_p[1] |= pack_right_shift_u32(battery_current, 8u, 0xffu);
    dst_p[2] |= pack_right_shift_u32(battery_current, 16u, 0xffu);
    dst_p[3] |= pack_right_shift_u32(battery_current, 24u, 0xffu);
    memcpy(&battery_voltage, &src_p->battery_voltage, sizeof(battery_voltage));
    dst_p[4] |= pack_left_shift_u32(battery_voltage, 0u, 0xffu);
    dst_p[5] |= pack_right_shift_u32(battery_voltage, 8u, 0xffu);
    dst_p[6] |= pack_right_shift_u32(battery_voltage, 16u, 0xffu);
    dst_p[7] |= pack_right_shift_u32(battery_voltage, 24u, 0xffu);
    memcpy(&ts_voltage, &src_p->ts_voltage, sizeof(ts_voltage));
    dst_p[8] |= pack_left_shift_u32(ts_voltage, 0u, 0xffu);
    dst_p[9] |= pack_right_shift_u32(ts_voltage, 8u, 0xffu);
    dst_p[10] |= pack_right_shift_u32(ts_voltage, 16u, 0xffu);
    dst_p[11] |= pack_right_shift_u32(ts_voltage, 24u, 0xffu);
    memcpy(&battery_power, &src_p->battery_power, sizeof(battery_power));
    dst_p[12] |= pack_left_shift_u32(battery_power, 0u, 0xffu);
    dst_p[13] |= pack_right_shift_u32(battery_power, 8u, 0xffu);
    dst_p[14] |= pack_right_shift_u32(battery_power, 16u, 0xffu);
    dst_p[15] |= pack_right_shift_u32(battery_power, 24u, 0xffu);
    dst_p[16] |= pack_left_shift_u8(src_p->ts_active, 0u, 0x01u);
    dst_p[16] |= pack_left_shift_u8(src_p->air_neg_closed, 1u, 0x02u);
    dst_p[16] |= pack_left_shift_u8(src_p->air_pos_closed, 2u, 0x04u);
    dst_p[17] |= pack_left_shift_u8(src_p->accu_state, 0u, 0xffu);

    return (20);
}

int ucr_03_accumulator_measurements_unpack(
    struct ucr_03_accumulator_measurements_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    uint32_t battery_current;
    uint32_t battery_power;
    uint32_t battery_voltage;
    uint32_t ts_voltage;

    if (size < 20u) {
        return (-EINVAL);
    }

    battery_current = unpack_right_shift_u32(src_p[0], 0u, 0xffu);
    battery_current |= unpack_left_shift_u32(src_p[1], 8u, 0xffu);
    battery_current |= unpack_left_shift_u32(src_p[2], 16u, 0xffu);
    battery_current |= unpack_left_shift_u32(src_p[3], 24u, 0xffu);
    memcpy(&dst_p->battery_current, &battery_current, sizeof(dst_p->battery_current));
    battery_voltage = unpack_right_shift_u32(src_p[4], 0u, 0xffu);
    battery_voltage |= unpack_left_shift_u32(src_p[5], 8u, 0xffu);
    battery_voltage |= unpack_left_shift_u32(src_p[6], 16u, 0xffu);
    battery_voltage |= unpack_left_shift_u32(src_p[7], 24u, 0xffu);
    memcpy(&dst_p->battery_voltage, &battery_voltage, sizeof(dst_p->battery_voltage));
    ts_voltage = unpack_right_shift_u32(src_p[8], 0u, 0xffu);
    ts_voltage |= unpack_left_shift_u32(src_p[9], 8u, 0xffu);
    ts_voltage |= unpack_left_shift_u32(src_p[10], 16u, 0xffu);
    ts_voltage |= unpack_left_shift_u32(src_p[11], 24u, 0xffu);
    memcpy(&dst_p->ts_voltage, &ts_voltage, sizeof(dst_p->ts_voltage));
    battery_power = unpack_right_shift_u32(src_p[12], 0u, 0xffu);
    battery_power |= unpack_left_shift_u32(src_p[13], 8u, 0xffu);
    battery_power |= unpack_left_shift_u32(src_p[14], 16u, 0xffu);
    battery_power |= unpack_left_shift_u32(src_p[15], 24u, 0xffu);
    memcpy(&dst_p->battery_power, &battery_power, sizeof(dst_p->battery_power));
    dst_p->ts_active = unpack_right_shift_u8(src_p[16], 0u, 0x01u);
    dst_p->air_neg_closed = unpack_right_shift_u8(src_p[16], 1u, 0x02u);
    dst_p->air_pos_closed = unpack_right_shift_u8(src_p[16], 2u, 0x04u);
    dst_p->accu_state = unpack_right_shift_u8(src_p[17], 0u, 0xffu);

    return (0);
}

